SEVERITY_RANK = {"high": 0, "medium": 1, "low": 2}


def identity(finding):
    summary = str(finding.get("summary", "")).strip().lower()
    return (finding.get("file", ""), finding.get("line") or 0, summary)


def order(finding):
    rank = SEVERITY_RANK.get(finding.get("severity"), len(SEVERITY_RANK))
    return (rank, finding.get("file", ""), finding.get("line") or 0)


def verdict(findings):
    if [finding for finding in findings if finding.get("severity") == "high"]:
        return "request_changes"
    if findings:
        return "comment"
    return "approve"


def run(security, correctness, readability):
    merged = {}
    reports = (
        ("security", security),
        ("correctness", correctness),
        ("readability", readability),
    )

    for reviewer, findings in reports:
        for finding in findings:
            key = identity(finding)
            if key in merged:
                merged[key]["reviewers"].append(reviewer)
            else:
                merged[key] = dict(finding, reviewers=[reviewer])

    findings = sorted(merged.values(), key=order)
    counts = {severity: 0 for severity in SEVERITY_RANK}
    for finding in findings:
        severity = finding.get("severity")
        if severity in counts:
            counts[severity] = counts[severity] + 1

    return {
        "review": {"verdict": verdict(findings), "findings": findings, "counts": counts},
        "has_findings": len(findings) > 0,
        "summary": "No issues found.",
    }
